True def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    wall_cols = [c for c in range(w) if all(grid[r][c] == 2 for r in range(h))]
    wall = wall_cols[0]
    counts = {}
    for row in grid:
        for v in row:
            if v != 2:
                counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    obj = [ (r,c) for r in range(h) for c in range(w) if grid[r][c] not in (2,bg) ]
    cols = [c for r,c in obj]
    if max(cols) < wall:
        line = min(cols) - 1
    else:
        line = max(cols) + 1
    for r in range(h):
        out[r][line] = 8
    return out
